import healthy from './healthy-order.json';
import slowDatabase from './slow-database.json';
import externalPayment from './external-payment.json';
import failingDependency from './failing-dependency.json';

export interface Sample {
  id: string;
  title: string;
  summary: string;
  scenario: 'healthy' | 'database' | 'external' | 'error';
  data: unknown;
}

/** Every sample here is synthetic: generated by scripts/generate-fixtures.py, not captured. */
export const SAMPLES: Sample[] = [
  {
    id: 'healthy-order',
    title: 'Healthy order request',
    summary: 'A POST /api/orders request completing normally in about 450 ms. Use it as a comparison baseline.',
    scenario: 'healthy',
    data: healthy,
  },
  {
    id: 'slow-database',
    title: 'Slow database query',
    summary: 'The same request where an inventory SELECT takes about 2.6 s, pushing the total past 3 s.',
    scenario: 'database',
    data: slowDatabase,
  },
  {
    id: 'external-payment',
    title: 'Slow external payment provider',
    summary: 'The payment service waits about 2.2 s on a card-network call, so the request takes about 2.5 s.',
    scenario: 'external',
    data: externalPayment,
  },
  {
    id: 'failing-dependency',
    title: 'Failing payment dependency',
    summary: 'The payment service returns 503 twice and the order request fails with a 502.',
    scenario: 'error',
    data: failingDependency,
  },
];

export function getSample(id: string): Sample | undefined {
  return SAMPLES.find((s) => s.id === id);
}
